package com.rohit.inventory.controller; import com.rohit.inventory.dto.response.ApiResponse; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/audit") public class AuditController { private final JdbcTemplate jdbc; public AuditController(JdbcTemplate jdbc){this.jdbc=jdbc;} @GetMapping @PreAuthorize("hasAuthority('AUDIT_READ')") public ApiResponse<List<Map<String,Object>>> list(@RequestParam(required=false)String action,@RequestParam(required=false)String entityType,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){int safe=Math.min(Math.max(size,1),100);int offset=Math.max(page,0)*safe;String sql="select id,actor_user_id,action,entity_type,entity_id,previous_state,new_state,reason,correlation_id,created_at from audit_logs where (? is null or action=?) and (? is null or entity_type=?) order by created_at desc limit ? offset ?";return ApiResponse.success("Audit records retrieved successfully",jdbc.queryForList(sql,action,action,entityType,entityType,safe,offset));} }
